/* ---- ISS model for fgemm10.s (200 x 32-bit words) ---- */
namespace red_fgemm10_s {
static bool is_nan32(uint32_t x) { return (x & 0x7FFFFFFFu) > 0x7F800000u; }
static bool is_inf32(uint32_t x) { return (x & 0x7FFFFFFFu) == 0x7F800000u; }
static bool is_zero32(uint32_t x) { return (x & 0x7FFFFFFFu) == 0u; }

// Finite nonzero operand -> significand with leading 1 at bit 23 and
// effective biased exponent (may be <= 0 for subnormals).
static void unpack(uint32_t x, int32_t &e, uint32_t &m) {
  uint32_t exp = (x >> 23) & 0xFFu;
  uint32_t frac = x & 0x7FFFFFu;
  if (exp == 0) {
    e = 1;
    m = frac;
    while ((m & 0x800000u) == 0) { m <<= 1; e--; }
  } else {
    e = (int32_t)exp;
    m = frac | 0x800000u;
  }
}

// sig has its leading 1 at bit 62; value = 1.f * 2^(E-127). Round RNE.
static uint32_t round_pack(uint32_t sign, int32_t E, uint64_t sig) {
  uint32_t s = sign << 31;
  int32_t shift = (E >= 1) ? 39 : 39 + (1 - E);
  if (shift > 63) return s;  // below half of the smallest subnormal
  uint64_t mant = sig >> shift;
  uint64_t rem = sig & ((1ull << shift) - 1ull);
  uint64_t half = 1ull << (shift - 1);
  if (rem > half || (rem == half && (mant & 1ull))) mant++;
  if (E >= 1) {
    uint64_t total = ((uint64_t)(uint32_t)(E - 1) << 23) + mant;
    if (total >= 0x7F800000ull) return s | 0x7F800000u;
    return s | (uint32_t)total;
  }
  return s | (uint32_t)mant;  // a carry into bit 23 yields the smallest normal
}

static uint32_t f32_mul_rne(uint32_t a, uint32_t b) {
  uint32_t sign = (a ^ b) >> 31;
  if (is_nan32(a) || is_nan32(b)) return 0x7FC00000u;
  if (is_inf32(a) || is_inf32(b)) {
    if (is_zero32(a) || is_zero32(b)) return 0x7FC00000u;
    return (sign << 31) | 0x7F800000u;
  }
  if (is_zero32(a) || is_zero32(b)) return sign << 31;
  int32_t ea, eb;
  uint32_t ma, mb;
  unpack(a, ea, ma);
  unpack(b, eb, mb);
  uint64_t p = (uint64_t)ma * (uint64_t)mb;  // in [2^46, 2^48)
  int32_t E = ea + eb - 127;
  uint64_t sig;
  if (p & (1ull << 47)) { sig = p << 15; E += 1; }
  else { sig = p << 16; }
  return round_pack(sign, E, sig);
}

static uint32_t f32_add_rne(uint32_t a, uint32_t b) {
  if (is_nan32(a) || is_nan32(b)) return 0x7FC00000u;
  if (is_inf32(a) || is_inf32(b)) {
    if (is_inf32(a) && is_inf32(b) && ((a ^ b) >> 31)) return 0x7FC00000u;
    return is_inf32(a) ? a : b;
  }
  if (is_zero32(a) && is_zero32(b)) return a & b & 0x80000000u;
  if (is_zero32(a)) return b;
  if (is_zero32(b)) return a;
  int32_t ea, eb;
  uint32_t ma, mb;
  unpack(a, ea, ma);
  unpack(b, eb, mb);
  uint32_t sa = a >> 31, sb = b >> 31;
  if (eb > ea || (eb == ea && mb > ma)) {
    int32_t te = ea; ea = eb; eb = te;
    uint32_t tm = ma; ma = mb; mb = tm;
    uint32_t ts = sa; sa = sb; sb = ts;
  }
  uint64_t A = (uint64_t)ma << 38;  // leading 1 at bit 61
  uint64_t B = (uint64_t)mb << 38;
  int32_t d = ea - eb;
  if (d >= 63) {
    B = 1;  // pure sticky
  } else if (d > 0) {
    uint64_t lost = B & ((1ull << d) - 1ull);
    B = (B >> d) | (lost ? 1ull : 0ull);
  }
  uint64_t s = (sa == sb) ? A + B : A - B;
  if (s == 0) return 0u;  // exact cancellation under RNE is +0
  int32_t lead = 63;
  while (((s >> lead) & 1ull) == 0) lead--;
  int32_t sh = 62 - lead;
  return round_pack(sa, ea + 1 - sh, s << sh);
}

void fgemm10_s_iss(const uint32_t in[200], uint32_t out[200]) {
  for (int i = 0; i < 10; i++) {
    for (int j = 0; j < 10; j++) {
      uint32_t acc = 0x00000000u;
      for (int k = 0; k < 10; k++) {
        uint32_t p = f32_mul_rne(in[10 * i + k], in[100 + 10 * k + j]);
        acc = f32_add_rne(acc, p);
      }
      uint32_t m = 0u - (is_nan32(acc) ? 1u : 0u);
      out[10 * i + j] = (0x7FC00000u & m) | (acc & ~m);
    }
  }
  for (int w = 100; w < 200; w++) out[w] = 0u;
}
}



static reg_t red_exec_fgemm10_s(processor_t* p, insn_t insn, reg_t pc)
{
  const reg_t src = RS1, dst = RS2;
  uint32_t in[200], out[200];

  for (int i = 0; i < 200; i++)
    in[i] = (uint32_t)MMU.load<uint32_t>(src + 4 * i);
  memset(out, 0, sizeof(out));

  red_fgemm10_s::fgemm10_s_iss(in, out);

  for (int i = 0; i < 200; i++)
    MMU.store<uint32_t>(dst + 4 * i, out[i]);

  WRITE_RD(0);
  return pc + 4;
}


